package controller;
import util.DBConnection;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.util.*;
public class AdminSupportServlet extends HttpServlet{private boolean admin(HttpSession h){return h!=null&&h.getAttribute("admin")!=null;}protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{if(!admin(q.getSession(false))){s.sendRedirect("admin-login.jsp");return;}List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT q.*,u.full_name,u.email FROM support_queries q JOIN users u ON u.user_id=q.user_id ORDER BY q.created_at DESC");ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"query_id","user_id","subject","message","admin_reply","status","created_at","full_name","email"})m.put(k,r.getObject(k));rows.add(m);}}catch(SQLException e){throw new ServletException(e);}q.setAttribute("queries",rows);q.getRequestDispatcher("admin-support.jsp").forward(q,s);}protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{if(!admin(q.getSession(false))){s.sendRedirect("admin-login.jsp");return;}try{int id=Integer.parseInt(q.getParameter("queryId"));String reply=q.getParameter("reply");String status=q.getParameter("status");if(reply==null||reply.length()>3000||!Arrays.asList("Open","In Progress","Answered","Closed").contains(status))throw new IllegalArgumentException();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE support_queries SET admin_reply=?,status=?,replied_at=CURRENT_TIMESTAMP WHERE query_id=?")){p.setString(1,reply.trim());p.setString(2,status);p.setInt(3,id);p.executeUpdate();}s.sendRedirect("admin-support");}catch(Exception e){s.sendError(400,"Invalid support response");}}}
